import { createEffect, createSignal, on, Show } from 'solid-js';
import type { JSX } from 'solid-js';
import {
  compatIndex, endpoint, errors, loadStatus, listPhase, listError,
} from '../../stores/corpus.js';
import { text } from '../../stores/view.js';
import './sparql.css';

export interface SparqlStateProps {

  children?: JSX.Element;
}

export function SparqlState(props: SparqlStateProps) {
  const ep = () => endpoint() || '';
  const busy = () => loadStatus() === 'loading';
  const reason = () => (errors()[0]?.message) || '';

  const firstPaint = () => listPhase() === 'first';

  // Phase 2 is not phase 0: between them the list phase is already null while
  // the load status is still loading, and the skeleton would flash back.
  const [hadPaint, setHadPaint] = createSignal(false);
  createEffect(() => {
    if (listPhase() === 'first') { setHadPaint(true); return; }
    const s = loadStatus();

    if (s !== 'loading') setHadPaint(false);
  });

  createEffect(on(endpoint, () => setHadPaint(false), { defer: true }));

  return (
    <section
      class="sparql-state"
      aria-busy={busy()}
      data-endpoint={ep() || undefined}
      data-list-phase={listPhase() || undefined}
      data-compat={compatIndex() ? 'true' : undefined}
    >
            <Show
        when={busy() && !firstPaint() && !hadPaint()}
        fallback={props.children}
      >
        <p class="sparql-laden skel-message" aria-live="polite">{text('load.queryEndpoint')}</p>
      </Show>

            <Show when={listPhase() === 'first'}>
        <div class="sparql-tail" aria-hidden="true">
          <span class="skel" /><span class="skel" /><span class="skel" />
        </div>
      </Show>

      <Show when={loadStatus() === 'error'}>
        <p class="src-err">
          {listError() === 'fullIndex'
            ? text('err.fullIndex', { ep: ep(), msg: reason() })
            : text('err.endpoint', { ep: ep(), msg: reason() })}
        </p>
      </Show>
    </section>
  );
}
